SELECT c.customer_id,'paid' AS cohort FROM customers c JOIN orders o ON o.customer_id=c.customer_id AND o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00' UNION ALL SELECT c.customer_id,'no_paid' AS cohort FROM customers c ANTI JOIN orders o ON o.customer_id=c.customer_id AND o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00' ORDER BY customer_id;
